// "Login with Google" — Google OAuth 2.0 / OpenID Connect.
//
// Plain server-side module (NO "use server") — imported only by the two Google
// auth route handlers under app/api/auth/google. Never bundled to the client;
// no client secret or token is ever logged or returned to the browser.
//
// Nxeon is a server-side Next.js app, so we are a CONFIDENTIAL client: the
// Authorization Code flow with a client secret (client_secret_post). Google is
// the identity provider; we only ever ask for the user's identity, never any
// Google API scope beyond `openid email profile`.
//
// ---------------------------------------------------------------------------
// PROTOCOL CONSTANTS — Google's OIDC endpoints (stable, from
// https://accounts.google.com/.well-known/openid-configuration):
//   * authorize  https://accounts.google.com/o/oauth2/v2/auth
//   * token      https://oauth2.googleapis.com/token
//   * userinfo   https://openidconnect.googleapis.com/v1/userinfo
// ---------------------------------------------------------------------------

import { randomBytes } from "node:crypto";

export const GOOGLE_AUTHORIZE_URL = "https://accounts.google.com/o/oauth2/v2/auth";
export const GOOGLE_TOKEN_URL = "https://oauth2.googleapis.com/token";
export const GOOGLE_USERINFO_URL = "https://openidconnect.googleapis.com/v1/userinfo";

/** The scopes we request: identity only. */
export const GOOGLE_OAUTH_SCOPES = "openid email profile";

/** Random URL-safe string for the CSRF `state`. */
export function randomUrlSafe(bytes = 32): string {
  return randomBytes(bytes).toString("base64url");
}

/**
 * Redirect URI — must be registered verbatim on the Google OAuth client.
 * `${APP_URL}/api/auth/google/callback`.
 */
export function googleRedirectUri(): string {
  const base = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");
  return `${base}/api/auth/google/callback`;
}

/**
 * Is the OAuth client configured in this environment? When false the login page
 * HIDES the "Continue with Google" button, so nothing shows a broken flow before
 * the operator adds the credentials. Read at request time (not module top-level)
 * so an unset value never crashes boot.
 */
export function googleOauthConfigured(): boolean {
  return Boolean(
    (process.env.GOOGLE_CLIENT_ID ?? "").trim() &&
      (process.env.GOOGLE_CLIENT_SECRET ?? "").trim(),
  );
}

/** Build the Google consent URL for this sign-in attempt. */
export function googleAuthorizeUrl(opts: { state: string }): string {
  const url = new URL(GOOGLE_AUTHORIZE_URL);
  url.searchParams.set("client_id", (process.env.GOOGLE_CLIENT_ID ?? "").trim());
  url.searchParams.set("redirect_uri", googleRedirectUri());
  url.searchParams.set("response_type", "code");
  url.searchParams.set("scope", GOOGLE_OAUTH_SCOPES);
  url.searchParams.set("state", opts.state);
  // We do not need offline access (no Google API calls after sign-in), so ask
  // for an online-only grant and always let the user pick the account.
  url.searchParams.set("access_type", "online");
  url.searchParams.set("prompt", "select_account");
  return url.toString();
}

// ---- Token endpoint --------------------------------------------------------

type TokenResponse = {
  access_token?: string;
  id_token?: string;
  expires_in?: number;
  scope?: string;
  token_type?: string;
  error?: string;
  error_description?: string;
};

/**
 * Exchange an authorization `code` for tokens (client_secret_post). Returns the
 * access token or a short, safe error string — NEVER the client secret or any
 * token in the error text.
 */
export async function googleExchangeCode(
  code: string,
): Promise<{ accessToken?: string; error?: string }> {
  const clientId = (process.env.GOOGLE_CLIENT_ID ?? "").trim();
  const clientSecret = (process.env.GOOGLE_CLIENT_SECRET ?? "").trim();

  const params = new URLSearchParams({
    code,
    client_id: clientId,
    client_secret: clientSecret,
    redirect_uri: googleRedirectUri(),
    grant_type: "authorization_code",
  });

  let res: Response;
  try {
    res = await fetch(GOOGLE_TOKEN_URL, {
      method: "POST",
      headers: {
        "Content-Type": "application/x-www-form-urlencoded",
        Accept: "application/json",
      },
      body: params.toString(),
      cache: "no-store",
    });
  } catch {
    return { error: "Couldn't reach Google to finish signing in. Try again shortly." };
  }

  let parsed: TokenResponse | null = null;
  try {
    parsed = (await res.json()) as TokenResponse;
  } catch {
    parsed = null;
  }

  if (!res.ok || !parsed?.access_token) {
    const detail = parsed?.error_description || parsed?.error || `HTTP ${res.status}`;
    return { error: `Google rejected the sign-in (${String(detail).slice(0, 160)}).` };
  }

  return { accessToken: parsed.access_token };
}

// ---- Userinfo --------------------------------------------------------------

export type GoogleProfile = {
  sub: string;
  email: string;
  emailVerified: boolean;
  name: string;
  picture: string | null;
};

type UserinfoResponse = {
  sub?: string;
  email?: string;
  email_verified?: boolean | string;
  name?: string;
  given_name?: string;
  picture?: string;
};

/**
 * Fetch the signed-in user's profile from the OIDC userinfo endpoint with the
 * bearer access token. Returns the normalised profile or a safe error string.
 * `emailVerified` normalises Google's boolean-or-"true"-string form.
 */
export async function googleFetchProfile(
  accessToken: string,
): Promise<{ profile?: GoogleProfile; error?: string }> {
  let res: Response;
  try {
    res = await fetch(GOOGLE_USERINFO_URL, {
      headers: { Authorization: `Bearer ${accessToken}`, Accept: "application/json" },
      cache: "no-store",
    });
  } catch {
    return { error: "Couldn't reach Google to read your profile. Try again shortly." };
  }

  let parsed: UserinfoResponse | null = null;
  try {
    parsed = (await res.json()) as UserinfoResponse;
  } catch {
    parsed = null;
  }

  if (!res.ok || !parsed?.sub || !parsed?.email) {
    return { error: "Google didn't return your profile. Please try again." };
  }

  const emailVerified = parsed.email_verified === true || parsed.email_verified === "true";
  return {
    profile: {
      sub: parsed.sub,
      email: parsed.email,
      emailVerified,
      name: (parsed.name ?? parsed.given_name ?? parsed.email.split("@")[0] ?? "").trim(),
      picture: parsed.picture ?? null,
    },
  };
}
import { NextRequest, NextResponse } from "next/server";
import { checkRateLimit, clientIp } from "@/lib/rate-limit";
import { safeNext } from "@/lib/safe-next";
import { googleAuthorizeUrl, googleOauthConfigured, randomUrlSafe } from "@/lib/google-oauth";

export const dynamic = "force-dynamic";

const base = () => (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");

/** httpOnly cookie carrying the CSRF `state` (and the return path) across the redirect. */
const STATE_COOKIE = "nx_google_oauth";

/**
 * Step 1 of "Login with Google": start the OAuth Authorization Code flow.
 *
 * Mints a CSRF `state`, stashes it (with the validated return path) in a
 * short-lived httpOnly cookie, then 302-redirects to Google's consent screen.
 * Nothing sensitive rides in the URL; the callback trusts only the cookie.
 *
 * No sign-in is required to reach this route — it is the sign-in itself.
 */
export async function GET(req: NextRequest) {
  // If the operator hasn't added credentials yet, don't send anyone into a
  // broken consent flow — bounce back to the login page. (The login page also
  // hides the button in this state; this is the belt-and-braces server guard.)
  if (!googleOauthConfigured()) {
    return NextResponse.redirect(`${base()}/login?error=google_unavailable`);
  }

  // Cheap abuse cap on starting the flow, keyed on the caller's IP.
  const rl = checkRateLimit(`google-oauth-start:${clientIp(req.headers)}`, {
    max: 20,
    windowMs: 60_000,
  });
  if (!rl.ok) {
    return NextResponse.redirect(`${base()}/login?error=google_ratelimited`);
  }

  const next = safeNext(req.nextUrl.searchParams.get("next"));
  const state = randomUrlSafe(24);

  const res = NextResponse.redirect(googleAuthorizeUrl({ state }));
  res.cookies.set({
    name: STATE_COOKIE,
    value: JSON.stringify({ state, next }),
    httpOnly: true,
    sameSite: "lax", // must survive the top-level redirect back from Google
    secure: base().startsWith("https://"),
    path: "/api/auth/google",
    maxAge: 600, // 10 minutes to complete consent
  });
  return res;
}
import { NextRequest, NextResponse } from "next/server";
import bcrypt from "bcryptjs";
import { recordRequestActivity } from "@/lib/activity-request";
import { db } from "@/lib/db";
import { createSession } from "@/lib/auth";
import { safeNext } from "@/lib/safe-next";
import { normalizeEmail } from "@/lib/email-normalize";
import { generateReferralCode, signupFreeCreditCents } from "@/lib/growth";
import { getSettingInt } from "@/lib/settings";
import { attachCustomerToPartnerByCode } from "@/lib/partner-commission";
import {
  googleExchangeCode,
  googleFetchProfile,
  googleOauthConfigured,
  randomUrlSafe,
} from "@/lib/google-oauth";

export const dynamic = "force-dynamic";

const base = () => (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");
const STATE_COOKIE = "nx_google_oauth";
/** Same cookie/convention as lib/actions.ts register() — set by /partner/<code>,
 *  /r/<code>, or a bare ?ref=<code> landing on /register (ReferralCapture). */
const REF_COOKIE = "nxeon_ref";

type Stash = { state?: string; next?: string };

/** Clear the one-shot state cookie on every exit path. */
function finish(res: NextResponse): NextResponse {
  res.cookies.set({ name: STATE_COOKIE, value: "", httpOnly: true, path: "/api/auth/google", maxAge: 0 });
  return res;
}

/** Bounce back to the login page with a short error code the page can show. */
function fail(code: string): NextResponse {
  return finish(NextResponse.redirect(`${base()}/login?error=${encodeURIComponent(code)}`));
}

/** A unique referral code, matching how `register()` seeds new accounts. */
async function uniqueReferralCode(): Promise<string> {
  for (let i = 0; i < 6; i++) {
    const code = generateReferralCode();
    const clash = await db.user.findUnique({ where: { referralCode: code } });
    if (!clash) return code;
  }
  return generateReferralCode(12);
}

/**
 * Step 2 of "Login with Google": the OAuth redirect target.
 *
 * Verifies CSRF `state` against the httpOnly cookie, exchanges the code for a
 * token, reads the OIDC profile, then finds/links/creates the local account and
 * issues the SAME session cookie a normal password login does (`createSession`).
 * No token is ever logged or placed in a URL. Any failure redirects to /login
 * with a friendly `error` code.
 *
 * NOTE: this is a Route Handler, NOT a `"use server"` action, so it adds no new
 * server-action endpoint and the customer-action guard test is unaffected.
 */
export async function GET(req: NextRequest) {
  if (!googleOauthConfigured()) return fail("google_unavailable");

  const raw = req.cookies.get(STATE_COOKIE)?.value;
  let stash: Stash = {};
  try {
    stash = raw ? (JSON.parse(raw) as Stash) : {};
  } catch {
    stash = {};
  }
  const next = safeNext(stash.next ?? null);

  const sp = req.nextUrl.searchParams;

  // The user declined on Google's consent screen, or Google itself errored
  // (e.g. the app is still in "testing" mode and this user isn't a test user).
  const oauthError = sp.get("error");
  if (oauthError) {
    return fail(oauthError === "access_denied" ? "google_cancelled" : "google_error");
  }

  // CSRF: the returned state must match the cookie minted by the start route.
  const state = sp.get("state") ?? "";
  if (!stash.state || !state || state !== stash.state) {
    return fail("google_state");
  }

  const code = sp.get("code") ?? "";
  if (!code) return fail("google_error");

  const exchanged = await googleExchangeCode(code);
  if (!exchanged.accessToken) return fail("google_error");

  const { profile } = await googleFetchProfile(exchanged.accessToken);
  if (!profile) return fail("google_error");

  // Google must have verified control of the address, else linking/creating an
  // account on it would trust an address the user never proved they own.
  if (!profile.emailVerified) return fail("google_unverified");

  const email = normalizeEmail(profile.email);
  if (!email) return fail("google_error");

  // 1) Existing Google link → sign in.
  let user = await db.user.findUnique({ where: { googleId: profile.sub } });

  // 2) Existing account by email → link Google onto it (lets a password user
  //    sign in with Google). Google already verified the address, so also stamp
  //    email verification if it was never proven locally.
  if (!user) {
    const byEmail = await db.user.findUnique({ where: { email } });
    if (byEmail) {
      user = await db.user.update({
        where: { id: byEmail.id },
        data: {
          googleId: profile.sub,
          avatarUrl: byEmail.avatarUrl ?? profile.picture,
          emailVerifiedAt: byEmail.emailVerifiedAt ?? new Date(),
        },
      });
      await db.auditLog
        .create({ data: { userId: user.id, action: "user.google_link", detail: "Linked Google to existing account" } })
        .catch(() => {});
    }
  }

  // 3) No account yet → create one. `passwordHash` is required and this account
  //    has no password, so store a random, unusable bcrypt hash: it can never
  //    match any input, so the account can't be password-logged-in until the
  //    user sets a password (via forgot-password). Google verified the email, so
  //    it starts verified.
  let isNewAccount = false;
  if (!user) {
    isNewAccount = true;
    const unusableHash = await bcrypt.hash(randomUrlSafe(24), 12);
    try {
      user = await db.user.create({
        data: {
          email,
          name: profile.name || email.split("@")[0] || "Nxeon user",
          passwordHash: unusableHash,
          googleId: profile.sub,
          avatarUrl: profile.picture,
          emailVerifiedAt: new Date(),
          referralCode: await uniqueReferralCode(),
        },
      });
    } catch {
      // Almost certainly a race on the unique email/googleId index — re-resolve.
      // This account was NOT created by this request, so it is not "genuinely
      // new" from our point of view — never attach a creator code to it below.
      isNewAccount = false;
      user =
        (await db.user.findUnique({ where: { googleId: profile.sub } })) ??
        (await db.user.findUnique({ where: { email } }));
      if (!user) return fail("google_error");
    }
    await db.auditLog
      .create({ data: { userId: user.id, action: "user.google_register", detail: "Signed up with Google" } })
      .catch(() => {});
    await recordRequestActivity({ type: "auth.signup", userId: user.id, label: "Signed up with Google", data: { method: "google" } }, { headers: req.headers });
    // Creator/partner code attribution — ONLY for a genuinely new account, same
    // rule and cookie as lib/actions.ts register(): a visitor never types this
    // code, it only ever arrives via the nxeon_ref cookie set by a real
    // /partner/<code> click (or a bare ?ref=<code> landing on /register), and it
    // is attached ONCE, at account creation — attachCustomerToPartnerByCode's
    // own existing-attachment check (backed by PartnerCustomer.customerId being
    // UNIQUE) makes this safe even in the rare double-submit race above.
    if (isNewAccount) {
      const refCode = req.cookies.get(REF_COOKIE)?.value?.trim().toUpperCase();
      if (refCode) {
        try {
          await attachCustomerToPartnerByCode(user.id, refCode);
        } catch (e) {
          console.error("[google] partner attach failed for", user.id, e);
        }
      }
    }
    // Parity with password signup: idempotent welcome credit + welcome email.
    // Google verified the email already, so no verification link is sent. The
    // credit claim only pays a row whose signupCreditCents is still 0, so a rare
    // concurrent-signup race can never pay twice.
    try {
      const cents = await getSettingInt("signup_free_credit_cents", signupFreeCreditCents());
      if (cents > 0) {
        const claimed = await db.user.updateMany({
          where: { id: user.id, signupCreditCents: 0 },
          data: { balanceCents: { increment: cents }, signupCreditCents: cents },
        });
        if (claimed.count > 0) {
          await db.walletTransaction.create({ data: { userId: user.id, amountCents: cents, description: "Welcome credit", fundsKind: "PROMO" } });
        }
      }
    } catch (e) {
      console.error("[google] signup credit grant failed for", user.id, e);
    }
    try {
      const { sendMail, emails } = await import("@/lib/mailer");
      const { getLocationStats } = await import("@/lib/email-data");
      const tpl = emails.welcome(user.name || "", { locations: await getLocationStats() });
      await sendMail({ to: user.email, subject: tpl.subject, html: tpl.html, userId: user.id, kind: "welcome" });
    } catch {
      /* welcome email is best-effort, exactly like password signup */
    }
  }

  if (user.suspended) return fail("account_suspended");

  await db.auditLog.create({ data: { userId: user.id, action: "user.login", detail: "Google" } }).catch(() => {});
  await recordRequestActivity({ type: "auth.login", userId: user.id, label: "Signed in with Google", data: { method: "google" } }, { headers: req.headers });

  // Issue the exact same session a password login issues.
  await createSession(user.id);

  const res = NextResponse.redirect(`${base()}${next ?? (user.role === "ADMIN" ? "/admin" : "/dashboard")}`);
  // Consumed above (or intentionally not attached to a pre-existing account) —
  // clear it exactly like register()'s jar.delete(REF_COOKIE), same path/reason.
  if (isNewAccount) res.cookies.set({ name: REF_COOKIE, value: "", path: "/", maxAge: 0 });
  return finish(res);
}
