import { createCyrusSession } from "@/lib/auth";
import { recordRequestActivity } from "@/lib/activity-request";
import { modBuilderAccess } from "@/lib/modbuilder/access";
import { safeCyrusNext } from "@/lib/cyrus/bridge/routing";
import { recordConversion, saveAttributionSnapshot } from "@/lib/cyrus/analytics/conversions";
import { CYRUS_ATTR_COOKIE, CYRUS_CONSENT_COOKIE } from "@/lib/cyrus/analytics/consent";
import { safeEqual, verifyAssertion, publicKeyFor } from "@/lib/cyrus/bridge/assertion";
import { BRIDGE_ERRORS } from "@/lib/cyrus/bridge/flow";
import { bridgeEmailBlocked, bridgeGate, claimOnce, go, limited, notFound, takeHandshake } from "@/lib/cyrus-bridge/server";

export const dynamic = "force-dynamic";

/**
 * cyrus.my callback: our state cookie (constant-time match, consumed), then Nxeon's assertion (Ed25519, exact
 * iss/aud/typ, our nonce, 120 s, single-use jti). The account is matched by its stable id ONLY (never email), must
 * exist, not be suspended and have a verified email. Then the Cyrus-host session cookie (lib/auth createCyrusSession),
 * parented to the Nxeon session that vouched for it.
 */
export async function GET(req: Request) {
  const cfg = bridgeGate(req, "cyrus");
  if (!cfg) return notFound();
  const fail = (code: keyof typeof BRIDGE_ERRORS) => go(`${cfg.cyrusOrigin}/sign-in?error=${code}`);
  if (limited(req, "callback")) return fail("ratelimited");
  const url = new URL(req.url);
  const st = await takeHandshake("cyrus");
  const state = url.searchParams.get("state") ?? "";
  if (!st || !state || !safeEqual(st.s, state)) return fail("state");
  const err = url.searchParams.get("error");
  if (err) return fail(err in BRIDGE_ERRORS ? (err as keyof typeof BRIDGE_ERRORS) : "access_denied");
  const v = verifyAssertion(url.searchParams.get("code"), { key: publicKeyFor("nxeon"), iss: cfg.nxeonOrigin, aud: cfg.cyrusOrigin, typ: "login", nonce: st.n, claimOnce });
  if (!v.ok) return fail("assertion");
  const user = await db.user.findUnique({ where: { id: v.claims.sub } });
  if (!user || user.suspended) return fail("account");
  if (await bridgeEmailBlocked(user)) return fail("unverified");
  await createCyrusSession(user.id, v.claims.sid ?? null);
  // r44: consent + attribution snapshot for the conversion sender; a fresh account counts as a sign_up (both inert
  // unless CYRUS_ATTRIBUTION / CYRUS_CONVERSIONS)
  {
    const ck = (n: string) => new RegExp(`(?:^|;\\s*)${n}=([^;]*)`).exec(req.headers.get("cookie") ?? "")?.[1] ?? null;
    if (await saveAttributionSnapshot(user.id, ck(CYRUS_CONSENT_COOKIE), ck(CYRUS_ATTR_COOKIE)).catch(() => false) && Date.now() - user.createdAt.getTime() < 3600_000)
      await recordConversion({ id: "sign_up", key: user.id, userId: user.id });
  }
  await recordRequestActivity({ type: "auth.login", userId: user.id, label: "Signed in to Cyrus (cyrus.my)", data: { method: "nxeon-sso" } }, { headers: req.headers });
  // Not on the private-beta list (and the studio is not public yet): the studio would 404, so land on the honest
  // "private beta" panel instead (/sign-in renders it for a signed-in account that may not build). A check error
  // never blocks: the destination's own gate decides.
  const dest = safeCyrusNext(st.next);
  const allowed = await modBuilderAccess(user).then((u) => !!u).catch(() => true);
  return go(`${cfg.cyrusOrigin}${allowed ? dest : `/sign-in?next=${encodeURIComponent(dest)}`}`);
}
