import { currentUser, cyrusParentSessionHash } from "@/lib/auth";
import { parseAuthorize, authorizeQuery, callbackUrl } from "@/lib/cyrus/bridge/flow";
import { mintAssertion, privateKeyFor } from "@/lib/cyrus/bridge/assertion";
import { bridgeGate, go, limited, notFound } from "@/lib/cyrus-bridge/server";

export const dynamic = "force-dynamic";

/** "Sign in with Cyrus": cyrus.my vouches for its session (itself minted from a Nxeon identity) back to Nxeon. */
export async function GET(req: Request) {
  const cfg = bridgeGate(req, "cyrus");
  if (!cfg) return notFound();
  const p = parseAuthorize(new URL(req.url).searchParams, "nxeon", cfg);
  if (!p) return Response.json({ error: "invalid_request" }, { status: 400 });
  if (limited(req, "handoff")) return go(callbackUrl(p, { error: "ratelimited" }));
  const user = await currentUser();
  if (!user) return go(`${cfg.cyrusOrigin}/sign-in?next=${encodeURIComponent(`/auth/handoff?${authorizeQuery(p)}`)}`);
  if (user.role !== "CUSTOMER") return go(callbackUrl(p, { error: "staff" }));
  const code = mintAssertion({ typ: "login", iss: cfg.cyrusOrigin, aud: cfg.nxeonOrigin, sub: user.id, nonce: p.nonce, sid: await cyrusParentSessionHash() }, privateKeyFor("cyrus"));
  return go(callbackUrl(p, { code }));
}
