import { currentUser, cyrusParentSessionHash, destroySession } from "@/lib/auth";
import { mintAssertion, privateKeyFor, randomToken } from "@/lib/cyrus/bridge/assertion";
import { bridgeGate, continueTo, go, notFound, sameOrigin } from "@/lib/cyrus-bridge/server";

export const dynamic = "force-dynamic";

/**
 * cyrus.my sign-out (POST, same origin). destroySession() on the Cyrus host revokes this session AND its parent Nxeon
 * session (shared database: the back-channel), then a signed single-use hop clears the Nxeon cookie (front-channel),
 * reached by a plain navigation (continueTo: CSP form-action would block a cross-origin redirect after a form POST).
 */
export async function POST(req: Request) {
  const cfg = bridgeGate(req, "cyrus");
  if (!cfg) return notFound();
  if (!sameOrigin(req, cfg.cyrusOrigin)) return Response.json({ error: "forbidden" }, { status: 403 });
  const user = await currentUser();
  const sid = await cyrusParentSessionHash();
  await destroySession();
  if (!user) return go(`${cfg.cyrusOrigin}/sign-in?signed_out=1`, 303);
  const t = mintAssertion({ typ: "logout", iss: cfg.cyrusOrigin, aud: cfg.nxeonOrigin, sub: user.id, nonce: randomToken(24), sid }, privateKeyFor("cyrus"));
  return continueTo(`${cfg.nxeonOrigin}/sso/cyrus/logout?t=${encodeURIComponent(t)}`);
}
