import { callbackUrls } from "@/lib/cyrus/bridge/config";
import { safeCyrusNext } from "@/lib/cyrus/bridge/routing";
import { authorizeQuery, cleanAttr } from "@/lib/cyrus/bridge/flow";
import { CYRUS_ATTR_COOKIE, CYRUS_CONSENT_COOKIE, allowedAttribution, attributionEnabled, decodeAttribution, encodeAttribution, parseConsent } from "@/lib/cyrus/analytics/consent";
import { cookies } from "next/headers";
import { beginHandshake, bridgeGate, go, limited, notFound } from "@/lib/cyrus-bridge/server";

export const dynamic = "force-dynamic";

/** cyrus.my -> Nxeon authorize, with a fresh state + nonce sealed into a host-only cookie on cyrus.my. */
export async function GET(req: Request) {
  const cfg = bridgeGate(req, "cyrus");
  if (!cfg) return notFound();
  if (limited(req, "start")) return go(`${cfg.cyrusOrigin}/sign-in?error=ratelimited`);
  const sp = new URL(req.url).searchParams;
  const mode = sp.get("mode") === "create" ? "create" : undefined;
  const st = await beginHandshake("cyrus", safeCyrusNext(sp.get("next")), mode);
  // r44 attribution hand-off (CYRUS_ATTRIBUTION): only what the person consented to, re-checked against the consent now
  let attr: string | undefined;
  if (attributionEnabled(process.env)) {
    const jar = await cookies();
    const a = allowedAttribution(decodeAttribution(jar.get(CYRUS_ATTR_COOKIE)?.value) ?? {}, parseConsent(jar.get(CYRUS_CONSENT_COOKIE)?.value));
    attr = cleanAttr(a ? encodeAttribution(a) : null);
  }
  const q = authorizeQuery({ clientId: "cyrus", redirectUri: callbackUrls(cfg).cyrus, state: st.s, nonce: st.n, prompt: mode ?? "login", ...(attr ? { attr } : {}) });
  return go(`${cfg.nxeonOrigin}/sso/cyrus/authorize?${q}`);
}
