// Cyrus one-account bridge, platform side: the route handlers' shared plumbing (mode gate, rate limits, the sealed
// state/consent cookies, absolute redirects). The protocol itself is lib/cyrus/bridge (seam-clean); this file is
// allowed to use Nxeon (lib/auth, lib/rate-limit) because it IS the identity provider and the session issuer.
import { NextResponse } from "next/server";
import { cookies } from "next/headers";
import { bridgeConfig, CYRUS_HOST_HEADER, ssoStateCookie, type BridgeConfig } from "@/lib/cyrus/bridge/config";
import { randomToken, seal, unseal } from "@/lib/cyrus/bridge/assertion";
import { checkRateLimit, claimOnce, clientIp } from "@/lib/rate-limit";
import { emailVerificationError, isEmailVerified, isGrandfathered } from "@/lib/email-verification";

export { claimOnce };
const prod = () => process.env.NODE_ENV === "production";

/** The handler's gate: mode on AND the request is on the expected side. Otherwise the route does not exist. */
export function bridgeGate(req: Request, side: "cyrus" | "nxeon"): BridgeConfig | null {
  const cfg = bridgeConfig();
  if (!cfg.enabled) return null;
  const onCyrus = req.headers.get(CYRUS_HOST_HEADER) === "1";
  return (side === "cyrus") === onCyrus ? cfg : null;
}
export const notFound = () => new NextResponse("Not found.", { status: 404 });

/** Per-IP limit for every bridge leg (handshakes are cheap to start; abuse should not be). */
export function limited(req: Request, bucket: string, max = 30): boolean {
  return !checkRateLimit(`cyrus-bridge:${bucket}:${clientIp(req)}`, { max, windowMs: 60_000 }).ok;
}

/** 302/303 to an absolute URL on one of the two configured origins, never cached, no Referer leak of codes. */
export function go(url: string, status: 302 | 303 = 302): NextResponse {
  const res = NextResponse.redirect(url, status);
  res.headers.set("Cache-Control", "no-store");
  res.headers.set("Referrer-Policy", "no-referrer");
  return res;
}

export type SsoState = { s: string; n: string; next: string; m?: "create" };
const STATE_TTL_S = 600;

/** Start a handshake: fresh state + nonce sealed into a host-only, httpOnly, Lax cookie on THIS side. */
export async function beginHandshake(side: "cyrus" | "nxeon", next: string, mode?: "create"): Promise<SsoState> {
  const st: SsoState = { s: randomToken(24), n: randomToken(24), next, ...(mode ? { m: mode } : {}) };
  (await cookies()).set(ssoStateCookie(side), seal(`state:${side}`, st, STATE_TTL_S), {
    httpOnly: true, sameSite: "lax", secure: prod(), path: "/", maxAge: STATE_TTL_S,
  });
  return st;
}
/** Read AND delete the handshake cookie (one callback per start). */
export async function takeHandshake(side: "cyrus" | "nxeon"): Promise<SsoState | null> {
  const jar = await cookies();
  const raw = jar.get(ssoStateCookie(side))?.value;
  // r49 (re-audit A-L1): a __Host- cookie can only be cleared by a Secure Set-Cookie (jar.delete sends none)
  jar.set(ssoStateCookie(side), "", { httpOnly: true, sameSite: "lax", secure: prod(), path: "/", maxAge: 0 });
  return unseal<SsoState & { e: number }>(`state:${side}`, raw);
}

// ---- consent (Nxeon side): remembered per browser + account; a pre-account grant covers one sign-up handshake.
const CONSENT_COOKIE = () => `${prod() ? "__Host-" : ""}nxeon_cyrus_consent`;
type Consent = { u?: string; pre?: string };
export async function hasConsent(userId: string, nonce: string): Promise<boolean> {
  const c = unseal<Consent & { e: number }>("consent", (await cookies()).get(CONSENT_COOKIE())?.value);
  return !!c && (c.u === userId || c.pre === nonce);
}
export async function grantConsent(g: { userId?: string; nonce?: string }): Promise<void> {
  const ttl = g.userId ? 365 * 86_400 : 1_800;
  (await cookies()).set(CONSENT_COOKIE(), seal("consent", g.userId ? { u: g.userId } : { pre: g.nonce }, ttl), {
    httpOnly: true, sameSite: "lax", secure: prod(), path: "/", maxAge: ttl,
  });
}
/** CSRF token for the consent form, bound to the handshake nonce and the account (or "" before sign-up). */
export const consentCsrf = (nonce: string, userId: string) => seal("consent-csrf", { n: nonce, u: userId }, 900);
export function checkConsentCsrf(raw: string | null, nonce: string, userId: string): boolean {
  const c = unseal<{ n: string; u: string; e: number }>("consent-csrf", raw);
  return !!c && c.n === nonce && c.u === userId;
}

/** Same-origin check for state-changing POSTs (in addition to SameSite=Lax cookies). */
export function sameOrigin(req: Request, origin: string): boolean {
  const o = req.headers.get("origin");
  return o === origin;
}

/**
 * Verified-email rule for the bridge. STRICT by default: the account must have confirmed its email (or predate
 * verification, like everywhere in Nxeon). Nxeon's own purchase gate fails open while mail deliverability is
 * unproven (email_verification_enforced); CYRUS_BRIDGE_REQUIRE_VERIFIED=0 makes the bridge follow that rule instead.
 */
export async function bridgeEmailBlocked(user: Parameters<typeof emailVerificationError>[0]): Promise<boolean> {
  if (process.env.CYRUS_BRIDGE_REQUIRE_VERIFIED === "0") return (await emailVerificationError(user)) !== null;
  return !isEmailVerified(user) && !isGrandfathered(user);
}

/**
 * After a FORM POST, continue with a plain navigation instead of a redirect: the site CSP has form-action 'self', and
 * browsers apply form-action to every redirect that follows a form submission, so a 303 that ends cross-origin
 * (consent -> authorize -> cyrus.my, cyrus.my logout -> Nxeon) would be blocked. `url` is always one we built.
 */
export function continueTo(url: string): Response {
  const esc = url.replace(/&/g, "&amp;").replace(/"/g, "&quot;").replace(/</g, "&lt;");
  return new Response(
    `<!doctype html><meta charset="utf-8"><meta name="referrer" content="no-referrer"><meta http-equiv="refresh" content="0;url=${esc}"><title>Continuing</title><p><a href="${esc}">Continue</a></p>`,
    { status: 200, headers: { "content-type": "text/html; charset=utf-8", "cache-control": "no-store", "referrer-policy": "no-referrer" } },
  );
}
// Dual-host routing decision for the Cyrus host (cyrus.my). PURE + Edge-safe: middleware.ts calls it, tests pin it.
// The same app serves both hosts; on the Cyrus host only the Cyrus surface exists, everything else is either handed
// to Nxeon (portal pages) or 404s. The marketing landing at "/" is nginx's static page; if "/" reaches the app it
// goes to the studio.
import type { BridgeConfig } from "./config";
import { APP_BASE, CYRUS_APP_PATHS } from "../app/flags";
import { HELP_BASE_INTERNAL, helpPath } from "../help/paths";

export type HostRoute =
  | { kind: "pass" }
  | { kind: "rewrite"; pathname: string }
  | { kind: "redirect"; url: string; status: 302 | 307 }
  | { kind: "notfound" };

const STATIC_RE = /\.(?:png|jpe?g|gif|webp|avif|svg|ico|mp4|webm|woff2?|css|json|txt|glb|gltf|ogg|wav)$/i;
const under = (p: string, prefix: string) => p === prefix || p.startsWith(prefix + "/");
/**
 * Trees whose handlers are real application routes, never files. A path under them that merely ENDS in a static
 * extension ("/api/invoices/x.png", "/admin/users/x.json") is a dynamic segment, not a file: it must go through the
 * allow-list below instead of the static pass (security review 2026-10-14, BQ-1).
 */
const NOT_FILE_TREES = ["/api", "/admin", "/staff", "/sso", "/dashboard", "/internal"];
export const isStaticFilePath = (p: string) => STATIC_RE.test(p) && !NOT_FILE_TREES.some((t) => under(p, t));

/** Internal tree for Cyrus-host-only pages; 404 on every other host. */
export const CYRUS_HOST_TREE = "/cyrus-host";

/** Auth pages and handlers that exist only on the Cyrus host (public path -> internal path). */
const CYRUS_PAGES: Record<string, string> = {
  "/sign-in": `${CYRUS_HOST_TREE}/sign-in`,
  "/sign-up": `${CYRUS_HOST_TREE}/sign-up`,
  "/auth/nxeon/start": `${CYRUS_HOST_TREE}/auth/start`,
  "/auth/nxeon/callback": `${CYRUS_HOST_TREE}/auth/callback`,
  "/auth/handoff": `${CYRUS_HOST_TREE}/auth/handoff`,
  "/auth/logout": `${CYRUS_HOST_TREE}/auth/logout`,
  // The legal documents are served ON cyrus.my (same documents as nxeon.cloud/legal/*; one operator, one account), so
  // no page of cyrus.my sends the visitor to nxeon.cloud just to read the terms.
  "/legal/terms": `${CYRUS_HOST_TREE}/legal/terms`,
  "/legal/privacy": `${CYRUS_HOST_TREE}/legal/privacy`,
  "/legal/aup": `${CYRUS_HOST_TREE}/legal/aup`,
  "/legal/sla": `${CYRUS_HOST_TREE}/legal/sla`,
  "/legal": `${CYRUS_HOST_TREE}/legal/terms`,
};

/** APIs the Cyrus screens call (same handlers as on Nxeon). */
// "/api/log" is the error boundary's logger (components/ErrorState.tsx); without it crashes on cyrus.my were never logged.
const CYRUS_APIS = ["/api/cyrus", "/api/mod-builder", "/api/nxlabs/cyrus", "/api/log"];

export function cyrusHostRoute(a: { pathname: string; search: string; method: string; cfg: BridgeConfig }): HostRoute {
  const p = a.pathname;
  const read = a.method === "GET" || a.method === "HEAD";
  // The internal tree is the rewrite target of the public auth paths (Next may run middleware again on it): on the
  // Cyrus host it is just another name for them. Off the Cyrus host middleware 404s it, and its pages/handlers
  // refuse to render without the marker this middleware alone sets.
  if (under(p, CYRUS_HOST_TREE)) return { kind: "pass" };
  if (p.startsWith("/_next/") || p === "/favicon.ico" || p.startsWith("/.well-known/") || p.startsWith("/vendor/") || isStaticFilePath(p)) return { kind: "pass" };
  if (read && under(p, HELP_BASE_INTERNAL)) return { kind: "pass" };
  if (CYRUS_APIS.some((x) => under(p, x))) return { kind: "pass" };
  if (under(p, "/dashboard/cyrus")) return { kind: "pass" };
  if (under(p, "/studio")) return { kind: "rewrite", pathname: "/dashboard/cyrus" + p.slice("/studio".length) };
  if (!read && under(p, "/legal")) return { kind: "notfound" };
  if (CYRUS_PAGES[p]) return { kind: "rewrite", pathname: CYRUS_PAGES[p] };
  // Customer app (r39): /home, /new, /account, /assets, /servers, /wallet, /projects[/<id>] are the app tree (its pages 404 while CYRUS_CUSTOMER_APP is off).
  const app = appPath(p); if (app) return { kind: "rewrite", pathname: app };
  if (!read) return { kind: "notfound" };
  // Help center (r50): public /help[/<slug>] is the rewrite source for the (cyrus-help) route group; it 404s while CYRUS_CUSTOMER_APP is off.
  const help = helpPath(p); if (help) return { kind: "rewrite", pathname: help };
  if (p === "/") return { kind: "redirect", url: "/studio", status: 302 };
  if (p === "/login") return { kind: "redirect", url: "/sign-in" + a.search, status: 302 };
  if (p === "/register") return { kind: "redirect", url: "/sign-up" + a.search, status: 302 };
  // Portal pages (servers, wallet, billing...) live on Nxeon: hand the visitor over, same path.
  if (under(p, "/dashboard")) return { kind: "redirect", url: a.cfg.nxeonOrigin + p + a.search, status: 302 };
  // /legal/<doc> is a rewrite (CYRUS_PAGES above); an unknown /legal path falls through to 404.
  return { kind: "notfound" };
}

/** Public customer-app path -> internal path (null = not an app path). */
export function appPath(p: string): string | null {
  if (CYRUS_APP_PATHS[p]) return CYRUS_APP_PATHS[p];
  if (p.startsWith("/projects/") && /^\/projects\/[A-Za-z0-9_-]{1,64}$/.test(p)) return APP_BASE + p;
  return null;
}

/** Same-site post-sign-in destination on the Cyrus host: a single-slash path into the Cyrus surface, else /studio. */
export function safeCyrusNext(raw: string | null | undefined): string {
  const s = String(raw ?? "");
  if (!/^\/(?![/\\])[^\s]*$/.test(s) || s.length > 1536 || s.includes("\\")) return "/studio";
  const path = s.split(/[?#]/)[0];
  if (under(path, "/studio") || under(path, "/dashboard/cyrus") || path === "/auth/handoff" || appPath(path)) return s;
  return "/studio";
}

// ---------------------------------------------------------------------------
// r51: the secret Cyrus admin host (CYRUS_ADMIN_HOST). Only the Cyrus admin exists there: /admin/cyrus/**, the admin
// login, the staff 2FA enrolment page, the APIs (each authenticates itself), Next internals and static files. Every
// other path 404s; "/" and "/admin" go to /admin/cyrus.
// ---------------------------------------------------------------------------
export function cyrusAdminHostRoute(a: { pathname: string; search: string; method: string }): HostRoute {
  const p = a.pathname;
  if (p.startsWith("/_next/") || p === "/favicon.ico" || p.startsWith("/.well-known/") || p.startsWith("/vendor/") || isStaticFilePath(p)) return { kind: "pass" };
  if (p.startsWith("/api/")) return { kind: "pass" };
  if (under(p, "/admin/cyrus") || p === "/admin/login") return { kind: "pass" };
  // Staff without 2FA are sent here by the admin layout (enforce_staff_2fa); account security only.
  if (p === "/dashboard/settings") return { kind: "pass" };
  const read = a.method === "GET" || a.method === "HEAD";
  if (read && (p === "/" || p === "/admin")) return { kind: "redirect", url: "/admin/cyrus", status: 302 };
  if (read && p === "/login") return { kind: "redirect", url: "/admin/login" + a.search, status: 302 };
  return { kind: "notfound" };
}

/** With CYRUS_ADMIN_HOST_ONLY=1: the Cyrus admin paths that must 404 on every other host. */
export const isCyrusAdminPath = (p: string) => under(p, "/admin/cyrus") || under(p, "/api/admin/cyrus");
import { NextRequest, NextResponse } from "next/server";
import NXM_LIVE_ROUTES from "./app/nxm/_data/live-routes.json";
import { anonModCacheControl } from "./lib/seo-cache";
import { guardListRequest } from "./lib/list-guard";
import { adminHostConfig, adminIpAllowed, bridgeConfig, isCyrusAdminHost, isCyrusHost, requestIp, CYRUS_ADMIN_HOST_HEADER, CYRUS_HOST_HEADER } from "./lib/cyrus/bridge/config";
import { cyrusAdminHostRoute, cyrusHostRoute, isCyrusAdminPath, CYRUS_HOST_TREE } from "./lib/cyrus/bridge/routing";

function hostList(envVar: string | undefined): string[] {
  return (envVar ?? "")
    .split(",")
    .map((s) => s.trim().toLowerCase())
    .filter(Boolean);
}

// Every file actually committed under public/ -- logos, game art, flags,
// brand assets, blog images, docs, fonts. None of it is per-customer or
// sensitive; it's already served unauthenticated at the same path on the
// main site, so exposing it on the admin/staff hosts too doesn't defeat the
// isolation below (that's about app pages like /dashboard, not static
// files). Without this, every <img> under public/ 404s on the admin/staff
// hosts -- found live 2026-09-14 when the What's New announcement preview
// (game art, screenshots, the Nxeon logo) rendered as broken images in the
// admin panel while the identical page worked fine for customers.
const STATIC_ASSET_RE =
  /\.(?:png|jpe?g|gif|webp|avif|svg|ico|mp4|webm|woff2?|css|json|txt|md|html)$/i;

/**
 * Reachable on every host regardless of portal mode: Next internals, the API
 * surface every portal's own client code calls (chat SSE, uploads, etc.),
 * the auth utility pages every login form links to, and static files under
 * public/. Everything else is scoped to exactly one portal below.
 */
function isUniversallyAllowed(pathname: string): boolean {
  return (
    pathname.startsWith("/_next") ||
    pathname.startsWith("/api/") ||
    pathname === "/favicon.ico" ||
    pathname.startsWith("/.well-known/") ||
    pathname === "/forgot-password" ||
    pathname === "/reset-password" ||
    // Both portal layouts redirect a staff/admin account without 2FA here to
    // enroll (enforce_staff_2fa) -- account security settings aren't
    // customer-specific, and blocking this would stand between a legitimate
    // staff member and the one page that lets them satisfy the requirement.
    pathname === "/dashboard/settings" ||
    STATIC_ASSET_RE.test(pathname) ||
    // public/ also ships two vendored JS trees the portals load at runtime: the
    // noVNC console client (admin impersonation / VNC console) and skinview3d.
    // `.js` is deliberately NOT in the extension list above (a bare .js path
    // elsewhere is not a public asset), so they are allowed by directory.
    pathname.startsWith("/novnc/") ||
    pathname.startsWith("/vendor/")
  );
}

/**
 * Confines the admin/staff hostnames to exactly their own portal.
 *
 * app/admin/layout.tsx and app/staff/layout.tsx already refuse the WRONG
 * direction -- /admin and /staff 404 on any host that isn't their own
 * NXEON_ADMIN_HOSTS/NXEON_STAFF_HOSTS. But nothing stopped the REVERSE: the
 * admin/staff hostnames proxy to the exact same Next.js backend as the main
 * site, so /dashboard, /login, /register, and every marketing page were
 * equally reachable there too -- confirmed live 2026-09-02, a customer's full
 * dashboard (wallet, deploy, domains) loading on the staff-only subdomain.
 * Not a data leak (they only ever saw their own account), but it defeats the
 * point of a separate, minimal, operations-only surface, and reduces
 * whatever "hard to guess" value the admin subdomain has by leaving it fully
 * browsable/indexable as a second copy of the public site.
 *
 * Together with the two layouts' existing checks this makes the mapping
 * exact: admin host <-> /admin only, staff host <-> /staff only, every other
 * host <-> everything except /admin and /staff.
 */
const NXM_EXACT = new Set<string>(NXM_LIVE_ROUTES.exact);
const NXM_PATTERNS = NXM_LIVE_ROUTES.patterns.map((p) => new RegExp(p));

export function middleware(req: NextRequest) {
  const host = (req.headers.get("host") ?? "").toLowerCase().split(":")[0];
  const { pathname } = req.nextUrl;

  // 2026-10-15 incident: deep-OFFSET scraping (/mods?page=8000) took the site down. Deep pages 404 and list-shaped
  // floods get a per-IP 429 here, before any page code or database query runs (lib/list-guard.ts).
  const guard = guardListRequest({ method: req.method, pathname, searchParams: req.nextUrl.searchParams, ip: requestIp(req.headers) });
  if (guard.block) {
    const headers: Record<string, string> = { "x-nxeon-guard": guard.reason, "x-robots-tag": "noindex" };
    if (guard.status === 429) {
      headers["retry-after"] = String(guard.retryAfterSec ?? 30);
      headers["cache-control"] = "no-store";
    } else headers["cache-control"] = "public, max-age=300";
    return new NextResponse(guard.status === 429 ? "Too many requests." : "Not found.", { status: guard.status, headers });
  }

  const adminHosts = hostList(process.env.NXEON_ADMIN_HOSTS);
  const staffHosts = hostList(process.env.NXEON_STAFF_HOSTS);
  const isAdminHost = adminHosts.length > 0 && adminHosts.includes(host);
  const isStaffHost = staffHosts.length > 0 && staffHosts.includes(host);

  // Cyrus dual-host (CYRUS_DOMAIN_MODE, off by default). The internal Cyrus-host page tree is never reachable by
  // its own URL; on the Cyrus host only the Cyrus surface exists (lib/cyrus/bridge/routing.ts). The marker header
  // is set ONLY here and stripped from every incoming request, so a client can never claim to be on the Cyrus host.
  if (pathname === CYRUS_HOST_TREE || pathname.startsWith(CYRUS_HOST_TREE + "/")) {
    return new NextResponse("Not found.", { status: 404 });
  }
  // r51 secret Cyrus admin host (CYRUS_ADMIN_HOST, off by default): only the Cyrus admin exists there, staff-only by the
  // admin layouts (Nxeon RBAC through the host seam), optional IP allowlist, noindex on every answer, 404 for the rest.
  const adminCfg = adminHostConfig();
  if (isCyrusAdminHost(host, adminCfg)) {
    const NOINDEX = { "x-robots-tag": "noindex, nofollow, noarchive", "cache-control": "no-store" };
    if (!adminIpAllowed(requestIp(req.headers), adminCfg)) return new NextResponse("Not found.", { status: 404, headers: NOINDEX });
    const r = cyrusAdminHostRoute({ pathname, search: req.nextUrl.search, method: req.method });
    if (r.kind === "notfound") return new NextResponse("Not found.", { status: 404, headers: NOINDEX });
    // absolute Location on the browser's own origin (scheme from nginx's X-Forwarded-Proto, host:port from Host), so
    // it is right behind the proxy; the host was matched exactly above, so it cannot point anywhere else
    if (r.kind === "redirect") {
      const xfp = (req.headers.get("x-forwarded-proto") ?? "").split(",")[0].trim();
      const proto = xfp === "https" || xfp === "http" ? xfp : req.nextUrl.protocol.replace(":", "");
      const res = NextResponse.redirect(new URL(r.url, `${proto}://${req.headers.get("host")}`), r.status);
      res.headers.set("x-robots-tag", NOINDEX["x-robots-tag"]);
      return res;
    }
    const h = new Headers(req.headers);
    h.delete(CYRUS_HOST_HEADER);
    h.set(CYRUS_ADMIN_HOST_HEADER, "1");
    h.set("x-pathname", pathname);
    h.set("x-search", req.nextUrl.search);
    const res = NextResponse.next({ request: { headers: h } });
    res.headers.set("x-robots-tag", NOINDEX["x-robots-tag"]);
    return res;
  }
  // After the move (CYRUS_ADMIN_HOST_ONLY=1) the Cyrus admin is gone from every other host, Nxeon admin hosts included.
  if (adminCfg.only && isCyrusAdminPath(pathname)) return new NextResponse("Not found.", { status: 404, headers: { "x-robots-tag": "noindex" } });

  const bridge = bridgeConfig();
  if (isCyrusHost(host, bridge)) {
    const r = cyrusHostRoute({ pathname, search: req.nextUrl.search, method: req.method, cfg: bridge });
    if (r.kind === "notfound") return new NextResponse("Not found.", { status: 404 });
    if (r.kind === "redirect") return NextResponse.redirect(new URL(r.url, bridge.cyrusOrigin), r.status);
    const h = new Headers(req.headers);
    h.delete(CYRUS_ADMIN_HOST_HEADER);
    h.set(CYRUS_HOST_HEADER, "1");
    h.set("x-pathname", r.kind === "rewrite" ? r.pathname : pathname);
    h.set("x-search", req.nextUrl.search);
    if (r.kind === "rewrite") {
      const url = req.nextUrl.clone();
      url.pathname = r.pathname;
      return NextResponse.rewrite(url, { request: { headers: h } });
    }
    return NextResponse.next({ request: { headers: h } });
  }

  // SEO: www.<apex> served a full 200 duplicate of the site (canonicals pointed at the apex, but
  // two crawlable hosts split link equity and crawl budget). 301 it to the canonical host.
  if (host.startsWith("www.") && !isAdminHost && !isStaffHost && (req.method === "GET" || req.method === "HEAD")) {
    try {
      const canon = new URL(process.env.APP_URL ?? "");
      if (host === `www.${canon.hostname}`) {
        const url = req.nextUrl.clone();
        url.protocol = canon.protocol;
        url.host = canon.host;
        url.port = canon.port;
        return NextResponse.redirect(url, 301);
      }
    } catch {
      /* APP_URL unset/invalid: leave www alone */
    }
  }

  // Draft site designs (app/newwebsitev1..v8): reachable by URL, linked from no live page, noindex.
  // They have no business on a production host at all, so 404 them unless an operator opts in
  // (NXEON_DRAFT_SITES=1, e.g. on a design sandbox). The files stay in the repo; nothing is deleted.
  if (process.env.NXEON_DRAFT_SITES !== "1" && /^\/newwebsitev[0-9]+(?:\/|$)/.test(pathname)) {
    return new NextResponse("Not found.", { status: 404, headers: { "x-robots-tag": "noindex" } });
  }

  // An admin impersonating a customer (lib/auth.ts's setImpersonation) needs to
  // browse the FULL customer app -- /dashboard, /checkout, etc. -- from their own
  // admin host, since impersonation swaps identity without changing host. Only
  // ADMIN can ever hold this cookie (EMPLOYEE/staff can never impersonate -- see
  // setImpersonation's own role check), so this only ever loosens the admin
  // host. We only check the cookie's PRESENCE here, not its signature/validity
  // -- that's exactly as strong as this gate needs to be: a forged or expired
  // token still gets fully re-verified by impersonating()/currentUser() at the
  // page/action layer, so a bad cookie here just falls back to "no session",
  // never to unauthorized access.
  const impCookieName = `${process.env.NXEON_COOKIE_NAME ?? "nxeon_session"}_imp`;
  const isImpersonating = isAdminHost && req.cookies.has(impCookieName);

  if ((isAdminHost || isStaffHost) && !isImpersonating) {
    const ownPrefix = isAdminHost ? "/admin" : "/staff";
    const ownLogin = isAdminHost ? "/admin/login" : "/staff/login";

    // The What's New admin preview renders the real customer dashboard
    // components, so it lives under /dashboard; the page itself is gated by
    // requireArea("platform"). Without this, the admin's own "Preview" link 404s.
    const adminPreview = isAdminHost && pathname.startsWith("/dashboard/whats-new/preview/");
    if (!isUniversallyAllowed(pathname) && !pathname.startsWith(ownPrefix) && !adminPreview) {
      // The shared /login page (and any stray redirect to it -- logout()
      // always sends there, regardless of who's logging out) lands on this
      // host's own dedicated login instead of 404ing a signed-out visitor.
      if (pathname === "/login") {
        const url = req.nextUrl.clone();
        url.pathname = ownLogin;
        return NextResponse.redirect(url);
      }
      // The bare root -- where someone typing/bookmarking just the hostname
      // lands -- goes to the portal itself rather than 404ing. The admin
      // vhost happens to have its own nginx-level `location = / return 302
      // /admin` that already covered this there (confirmed live), but the
      // staff vhost has no equivalent, so its root 404'd under this same
      // isolation logic. Handling it here covers both hosts the same way
      // regardless of nginx config: an authenticated visit shows the portal,
      // an unauthenticated one gets bounced on to ownLogin by the layout's
      // own existing redirect -- no new auth logic needed either way.
      if (pathname === "/") {
        const url = req.nextUrl.clone();
        url.pathname = ownPrefix;
        return NextResponse.redirect(url);
      }
      return new NextResponse("Not found.", { status: 404 });
    }
  }

  // Server Components have no built-in way to read the current pathname --
  // app/admin/layout.tsx and app/staff/layout.tsx need it to special-case
  // their own /login sub-route (public, no Shell, no auth redirect) without
  // a redirect loop. Set on the REQUEST (not the response) so headers() in a
  // downstream Server Component actually sees it.
  const requestHeaders = new Headers(req.headers);
  requestHeaders.delete(CYRUS_HOST_HEADER);
  requestHeaders.delete(CYRUS_ADMIN_HOST_HEADER);
  requestHeaders.set("x-pathname", pathname);
  // Same reasoning, for the query string: app/dashboard/layout.tsx's
  // logged-out redirect needs the FULL URL a marketing "Deploy" button sent a
  // visitor to (e.g. `/dashboard/deploy?product=game&family=valheim&tier=...`,
  // see lib/deploy-intent.ts) so it can send them to `/login?next=<that URL>`
  // instead of a bare `/login` that drops the selection the customer already
  // made. Kept separate from `x-pathname` rather than folded into it so every
  // existing exact-pathname comparison (`pathname === "/admin/login"`, etc.)
  // keeps working unchanged.
  requestHeaders.set("x-search", req.nextUrl.search);

  // The new marketing site (app/nxm) at the real URLs — the launch switch.
  // With NXM_ROOT=1 every URL it owns (app/nxm/_data/live-routes.json, from
  // scripts/nxm-live-routes.ts) is served from app/nxm, and any /nxm/<route>
  // link left over from staging 301s to its real URL. Unset NXM_ROOT and
  // restart to roll back to the old marketing pages instantly — they're
  // untouched. Main host only; admin/staff hosts returned above.
  if (process.env.NXM_ROOT === "1" && !isAdminHost && !isStaffHost) {
    if (pathname === "/nxm" || pathname.startsWith("/nxm/")) {
      if ((req.method === "GET" || req.method === "HEAD") && !/\.[a-z0-9]{2,5}$/i.test(pathname)) {
        const url = req.nextUrl.clone();
        url.pathname = pathname.slice(4) || "/";
        return NextResponse.redirect(url, 301);
      }
    } else if (!isCyrusModsPath(pathname) && (NXM_EXACT.has(pathname) || NXM_PATTERNS.some((re) => re.test(pathname)))) {
      const url = req.nextUrl.clone();
      url.pathname = pathname === "/" ? "/nxm" : "/nxm" + pathname;
      const res = NextResponse.rewrite(url, { request: { headers: requestHeaders } });
      // Anonymous mod pages may be cached by a shared cache / revalidated cheaply (lib/seo-cache.ts); never when a session cookie is present.
      const cc = anonModCacheControl({ method: req.method, pathname, search: req.nextUrl.search, cookie: req.headers.get("cookie"), authorization: req.headers.get("authorization"), sessionCookieName: process.env.NXEON_COOKIE_NAME ?? "nxeon_session" });
      if (cc) { res.headers.set("Cache-Control", cc); res.headers.append("Vary", "Cookie"); }
      return res;
    }
  }
  return NextResponse.next({ request: { headers: requestHeaders } });
}

/**
 * NxLabs "Cyrus Mods" (/mods/cyrus, /mods/cyrus/<slug>) is served by app/(marketing)/mods/cyrus
 * even with NXM_ROOT on: the nxm pattern ^/mods/[^/]+/[^/]+$ would otherwise send /mods/cyrus/<slug>
 * to the catalogue mod page, and gated per-viewer pages must never get the anonymous cache header.
 */
function isCyrusModsPath(p: string): boolean {
  return p === "/mods/cyrus" || p.startsWith("/mods/cyrus/");
}

export const config = {
  matcher: ["/((?!_next/static|_next/image).*)"],
};

  // `opts.revokeOtherSessions` mirrors the sessionVersion bump above at the
  // UserSession layer: changePassword and signOutOtherSessions both invalidate
  // every OTHER outstanding token via sessionVersion, then call createSession to
  // re-issue one for the caller's own device. Without this, the rows those older
  // tokens were tracked under (if any) would keep showing as "active" in
  // Settings even though sessionVersion has already made them unusable.
  if (opts?.revokeOtherSessions) {
    await db.userSession
      .updateMany({ where: { userId, revokedAt: null }, data: { revokedAt: new Date() } })
      .catch(() => {});
  }
  await trackSession(userId, token);
}

export async function destroySession() {
  const jar = await cookies();
  const { name, cyrus } = await sessionCookie();
  // Cyrus one-account bridge (CYRUS_DOMAIN_MODE only): signing out also REVOKES the session row, which is what ends
  // every Cyrus-host session minted from it (logout propagation; see realUser's parent check). Flag off: unchanged.
  if (bridgeConfig().enabled) {
    const token = jar.get(name)?.value;
    if (token) {
      await revokeSessionHash(sessionTokenHash(token));
      if (cyrus) {
        const psh = await parentOf(token);
        if (psh) await revokeSessionHash(psh);
      }
    }
  }
  if (cyrus) {
