// Find / link / create the Nxeon account for a verified Google profile. Plain server-side module (NOT "use server").
//
// Extracted VERBATIM from app/api/auth/google/callback/route.ts so the nxeon.cloud callback and the cyrus.my callback
// (app/cyrus-host/auth/google/callback) share ONE linking rule and ONE signup path (welcome credit, audit rows,
// partner attribution, welcome email). The caller has already checked `profile.emailVerified` and suspension.
import bcrypt from "bcryptjs";
import { recordRequestActivity } from "@/lib/activity-request";
import { db } from "@/lib/db";
import { normalizeEmail } from "@/lib/email-normalize";
import { generateReferralCode, signupFreeCreditCents } from "@/lib/growth";
import { getSettingInt } from "@/lib/settings";
import { attachCustomerToPartnerByCode } from "@/lib/partner-commission";
import { randomUrlSafe, type GoogleProfile } from "@/lib/google-oauth";

/** A unique referral code, matching how `register()` seeds new accounts. */
async function uniqueReferralCode(): Promise<string> {
  for (let i = 0; i < 6; i++) {
    const code = generateReferralCode();
    const clash = await db.user.findUnique({ where: { referralCode: code } });
    if (!clash) return code;
  }
  return generateReferralCode(12);
}

export type GoogleAccountResult =
  | { ok: true; user: NonNullable<Awaited<ReturnType<typeof db.user.findUnique>>>; isNewAccount: boolean }
  | { ok: false; error: "google_error" };

/**
 * 1) existing Google link -> that account; 2) existing account with the same (Google-verified) email -> link Google
 * onto it; 3) otherwise create a verified account with an unusable password hash. `refCode` is the creator/partner
 * code (nxeon.cloud's nxeon_ref cookie) and is attached ONLY for a genuinely new account.
 */
export async function findOrCreateGoogleAccount(
  profile: GoogleProfile,
  opts: { headers: Headers; refCode?: string | null },
): Promise<GoogleAccountResult> {
  const email = normalizeEmail(profile.email);
  if (!email) return { ok: false, error: "google_error" };

  // 1) Existing Google link → sign in.
  let user = await db.user.findUnique({ where: { googleId: profile.sub } });

  // 2) Existing account by email → link Google onto it (lets a password user
  //    sign in with Google). Google already verified the address, so also stamp
  //    email verification if it was never proven locally.
  if (!user) {
    const byEmail = await db.user.findUnique({ where: { email } });
    if (byEmail) {
      user = await db.user.update({
        where: { id: byEmail.id },
        data: {
          googleId: profile.sub,
          avatarUrl: byEmail.avatarUrl ?? profile.picture,
          emailVerifiedAt: byEmail.emailVerifiedAt ?? new Date(),
        },
      });
      await db.auditLog
        .create({ data: { userId: user.id, action: "user.google_link", detail: "Linked Google to existing account" } })
        .catch(() => {});
    }
  }

  // 3) No account yet → create one. `passwordHash` is required and this account
  //    has no password, so store a random, unusable bcrypt hash: it can never
  //    match any input, so the account can't be password-logged-in until the
  //    user sets a password (via forgot-password). Google verified the email, so
  //    it starts verified.
  let isNewAccount = false;
  if (!user) {
    isNewAccount = true;
    const unusableHash = await bcrypt.hash(randomUrlSafe(24), 12);
    try {
      user = await db.user.create({
        data: {
          email,
          name: profile.name || email.split("@")[0] || "Nxeon user",
          passwordHash: unusableHash,
          googleId: profile.sub,
          avatarUrl: profile.picture,
          emailVerifiedAt: new Date(),
          referralCode: await uniqueReferralCode(),
        },
      });
    } catch {
      // Almost certainly a race on the unique email/googleId index — re-resolve.
      // This account was NOT created by this request, so it is not "genuinely
      // new" from our point of view — never attach a creator code to it below.
      isNewAccount = false;
      user =
        (await db.user.findUnique({ where: { googleId: profile.sub } })) ??
        (await db.user.findUnique({ where: { email } }));
      if (!user) return { ok: false, error: "google_error" };
    }
    await db.auditLog
      .create({ data: { userId: user.id, action: "user.google_register", detail: "Signed up with Google" } })
      .catch(() => {});
    await recordRequestActivity({ type: "auth.signup", userId: user.id, label: "Signed up with Google", data: { method: "google" } }, { headers: opts.headers });
    // Creator/partner code attribution — ONLY for a genuinely new account, same
    // rule as lib/actions.ts register(); attached ONCE, at account creation.
    if (isNewAccount) {
      const refCode = opts.refCode?.trim().toUpperCase();
      if (refCode) {
        try {
          await attachCustomerToPartnerByCode(user.id, refCode);
        } catch (e) {
          console.error("[google] partner attach failed for", user.id, e);
        }
      }
    }
    // Parity with password signup: idempotent welcome credit + welcome email.
    try {
      const cents = await getSettingInt("signup_free_credit_cents", signupFreeCreditCents());
      if (cents > 0) {
        const claimed = await db.user.updateMany({
          where: { id: user.id, signupCreditCents: 0 },
          data: { balanceCents: { increment: cents }, signupCreditCents: cents },
        });
        if (claimed.count > 0) {
          await db.walletTransaction.create({ data: { userId: user.id, amountCents: cents, description: "Welcome credit", fundsKind: "PROMO" } });
        }
      }
    } catch (e) {
      console.error("[google] signup credit grant failed for", user.id, e);
    }
    try {
      const { sendMail, emails } = await import("@/lib/mailer");
      const { getLocationStats } = await import("@/lib/email-data");
      const tpl = emails.welcome(user.name || "", { locations: await getLocationStats() });
      await sendMail({ to: user.email, subject: tpl.subject, html: tpl.html, userId: user.id, kind: "welcome" });
    } catch {
      /* welcome email is best-effort, exactly like password signup */
    }
  }

  return { ok: true, user, isNewAccount };
}
