import { NextRequest, NextResponse } from "next/server";
import { recordRequestActivity } from "@/lib/activity-request";
import { createSession } from "@/lib/auth";
import { safeNext } from "@/lib/safe-next";
import { findOrCreateGoogleAccount } from "@/lib/google-account";
import {
  googleExchangeCode,
  googleFetchProfile,
  googleOauthConfigured,
} from "@/lib/google-oauth";

export const dynamic = "force-dynamic";

const base = () => (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");
const STATE_COOKIE = "nx_google_oauth";
/** Same cookie/convention as lib/actions.ts register() — set by /partner/<code>,
 *  /r/<code>, or a bare ?ref=<code> landing on /register (ReferralCapture). */
const REF_COOKIE = "nxeon_ref";

type Stash = { state?: string; next?: string };

/** Clear the one-shot state cookie on every exit path. */
function finish(res: NextResponse): NextResponse {
  res.cookies.set({ name: STATE_COOKIE, value: "", httpOnly: true, path: "/api/auth/google", maxAge: 0 });
  return res;
}

/** Bounce back to the login page with a short error code the page can show. */
function fail(code: string): NextResponse {
  return finish(NextResponse.redirect(`${base()}/login?error=${encodeURIComponent(code)}`));
  }

  const code = sp.get("code") ?? "";
  if (!code) return fail("google_error");

  const exchanged = await googleExchangeCode(code);
  if (!exchanged.accessToken) return fail("google_error");

  const { profile } = await googleFetchProfile(exchanged.accessToken);
  if (!profile) return fail("google_error");

  // Google must have verified control of the address, else linking/creating an
  // account on it would trust an address the user never proved they own.
  if (!profile.emailVerified) return fail("google_unverified");

  const refCode = req.cookies.get(REF_COOKIE)?.value;
  const acct = await findOrCreateGoogleAccount(profile, { headers: req.headers, refCode });
  if (!acct.ok) return fail(acct.error);
  const { user, isNewAccount } = acct;

  if (user.suspended) return fail("account_suspended");

  await db.auditLog.create({ data: { userId: user.id, action: "user.login", detail: "Google" } }).catch(() => {});
  await recordRequestActivity({ type: "auth.login", userId: user.id, label: "Signed in with Google", data: { method: "google" } }, { headers: req.headers });

  // Issue the exact same session a password login issues.
  await createSession(user.id);

  const res = NextResponse.redirect(`${base()}${next ?? (user.role === "ADMIN" ? "/admin" : "/dashboard")}`);
  // Consumed above (or intentionally not attached to a pre-existing account) —
  // clear it exactly like register()'s jar.delete(REF_COOKIE), same path/reason.
  if (isNewAccount) res.cookies.set({ name: REF_COOKIE, value: "", path: "/", maxAge: 0 });
  return finish(res);
}

