import { conversionSweep, conversionEventId, recordConversion, type ConversionDeps, type ConversionRow } from "../lib/cyrus/analytics/conversions";
import { encodeAttribution, serializeConsent } from "../lib/cyrus/analytics/consent";
import { authorizeQuery, cleanAttr, parseAuthorize } from "../lib/cyrus/bridge/flow";
import { callbackUrls } from "../lib/cyrus/bridge/config";
import { partnerCodeFrom } from "../lib/cyrus-bridge/attribution";

const ON = { CYRUS_CONVERSIONS: "1" };
const NOW = Date.parse("2026-10-11T10:00:00Z");
function deps(o: { consent?: string | null; attr?: string | null; transport?: ConversionDeps["transport"] } = {}) {
  const rows: (ConversionRow & { lastError?: string | null })[] = [];
  const sent: Record<string, unknown>[] = [];
  const d: ConversionDeps = {
    async insert(r) { if (rows.some((x) => x.id === r.id)) return false; rows.push({ ...r, status: "pending", attempts: 0, createdAt: new Date(NOW) }); return true; },
    async due() { return rows.filter((r) => r.status === "pending"); },
    async mark(id, p) { Object.assign(rows.find((r) => r.id === id)!, p); },
    async snapshot() { return o.consent === undefined ? { consent: serializeConsent({ analytics: true, marketing: true }, NOW), attr: o.attr ?? null } : { consent: o.consent, attr: o.attr ?? null }; },
    async emailSha256() { return "a".repeat(64); },
    transport: o.transport === undefined ? { meta: async (e) => { sent.push(e); return true; }, google: async () => false } : o.transport,
  };
  return { d, rows, sent };
}

describe("r44 conversion sender", () => {
  it("off: records nothing and sends nothing", async () => {
    const { d, rows } = deps();
    assert.equal(await recordConversion({ id: "sign_up", key: "u1", userId: "u1" }, d, {}), false);
    assert.deepEqual(await conversionSweep(d, {}), { sent: 0, skipped: 0, retried: 0, failed: 0 });
    assert.equal(rows.length, 0);
  });
  it("one event per deterministic id; sent with marketing consent, payload is the r40 spec", async () => {
    const { d, rows, sent } = deps({ attr: encodeAttribution({ click: { fbclid: "fbclid12345" } }) });
    assert.equal(await recordConversion({ id: "purchase", key: "inv_1", userId: "u1", valueCents: 1500 }, d, ON), true);
    assert.equal(await recordConversion({ id: "purchase", key: "inv_1", userId: "u1", valueCents: 1500 }, d, ON), false);
    const r = await conversionSweep(d, ON);
    assert.equal(r.sent, 1); assert.equal(rows[0].status, "sent"); assert.equal(rows[0].id, conversionEventId("purchase", "inv_1"));

