// Cyrus (cyrus.my) client — a SEPARATE Google OAuth client so Google's consent screen shows Cyrus branding.
// Everything above is untouched: the Nxeon functions keep reading GOOGLE_CLIENT_ID/SECRET + APP_URL exactly as before.
//
//   CYRUS_GOOGLE_LOGIN=1            the switch (default off)
//   CYRUS_GOOGLE_CLIENT_ID          the "Cyrus oAuth" client id
//   CYRUS_GOOGLE_CLIENT_SECRET      its secret (never logged, never returned)
//
// The Cyrus flow adds PKCE (S256) and an OIDC nonce on top of state; redirect_uri is derived from the Cyrus origin
// (CYRUS_ORIGIN / first CYRUS_HOSTS entry), never from a request header, so it can only ever be the registered URI.
// ---------------------------------------------------------------------------
import { createHash } from "node:crypto";
import { bridgeConfig, isCyrusHost } from "@/lib/cyrus/bridge/config";

type Env = Record<string, string | undefined>;

export type GoogleClient = { kind: "nxeon" | "cyrus"; clientId: string; clientSecret: string; redirectUri: string };

/** The path both hosts use; on cyrus.my middleware rewrites it to app/cyrus-host/auth/google/callback. */
export const GOOGLE_CALLBACK_PATH = "/api/auth/google/callback";

export function cyrusGoogleConfigured(env: Env = process.env): boolean {
  return (
    env.CYRUS_GOOGLE_LOGIN === "1" &&
    bridgeConfig(env).enabled &&
    Boolean((env.CYRUS_GOOGLE_CLIENT_ID ?? "").trim() && (env.CYRUS_GOOGLE_CLIENT_SECRET ?? "").trim())
  );
}

/** `https://<cyrus host>/api/auth/google/callback` — the exact string the owner registers on the Cyrus client. */
export function cyrusGoogleRedirectUri(env: Env = process.env): string {
  return `${bridgeConfig(env).cyrusOrigin}${GOOGLE_CALLBACK_PATH}`;
}

/**
 * Host-aware client selection. A Cyrus host gets the Cyrus client (null when it is not configured: a Cyrus host never
 * falls back to the Nxeon client, which would show Nxeon branding and a redirect URI it has not registered).
 * Any other host gets the Nxeon client, unchanged.
 */
export function googleClientForHost(host: string | null | undefined, env: Env = process.env): GoogleClient | null {
  if (isCyrusHost(host, bridgeConfig(env))) {
    if (!cyrusGoogleConfigured(env)) return null;
    return {
      kind: "cyrus",
      clientId: (env.CYRUS_GOOGLE_CLIENT_ID ?? "").trim(),
      clientSecret: (env.CYRUS_GOOGLE_CLIENT_SECRET ?? "").trim(),
      redirectUri: cyrusGoogleRedirectUri(env),
    };
  }
  if (!googleOauthConfigured()) return null;
  return {
    kind: "nxeon",
    clientId: (env.GOOGLE_CLIENT_ID ?? "").trim(),
    clientSecret: (env.GOOGLE_CLIENT_SECRET ?? "").trim(),
    redirectUri: googleRedirectUri(),
  };
}

/** RFC 7636 S256 challenge for a verifier. */
export const pkceChallenge = (verifier: string) => createHash("sha256").update(verifier).digest("base64url");

export function googleClientAuthorizeUrl(c: GoogleClient, o: { state: string; nonce?: string; codeChallenge?: string }): string {
  const url = new URL(GOOGLE_AUTHORIZE_URL);
  url.searchParams.set("client_id", c.clientId);
  url.searchParams.set("redirect_uri", c.redirectUri);
  url.searchParams.set("response_type", "code");
  url.searchParams.set("scope", GOOGLE_OAUTH_SCOPES);
  url.searchParams.set("state", o.state);
  if (o.nonce) url.searchParams.set("nonce", o.nonce);
  if (o.codeChallenge) {
    url.searchParams.set("code_challenge", o.codeChallenge);
    url.searchParams.set("code_challenge_method", "S256");
  }
  url.searchParams.set("access_type", "online");
  url.searchParams.set("prompt", "select_account");
  return url.toString();
}

/** Decode the (TLS-delivered, straight from Google's token endpoint) id_token payload; never trusted from a URL. */
function idTokenClaims(idToken: string | undefined): Record<string, unknown> | null {
  const part = (idToken ?? "").split(".")[1];
  if (!part) return null;
  try {
    return JSON.parse(Buffer.from(part, "base64url").toString("utf8")) as Record<string, unknown>;
  } catch {
    return null;
  }
}

/**
 * Code exchange for an explicit client, with the PKCE verifier. When `nonce` is given the id_token must carry it, an
 * `aud` equal to this client id and a Google `iss`. Returns the access token or a short safe error code.
 */
export async function googleClientExchange(
  c: GoogleClient,
  code: string,
  o: { codeVerifier?: string; nonce?: string } = {},
): Promise<{ accessToken?: string; sub?: string; error?: "network" | "rejected" | "nonce" }> {
  const params = new URLSearchParams({
    code,
    client_id: c.clientId,
    client_secret: c.clientSecret,
    redirect_uri: c.redirectUri,
    grant_type: "authorization_code",
  });
  if (o.codeVerifier) params.set("code_verifier", o.codeVerifier);

  let res: Response;
  try {
    res = await fetch(GOOGLE_TOKEN_URL, {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded", Accept: "application/json" },
      body: params.toString(),
      cache: "no-store",
    });
  } catch {
    return { error: "network" };
  }
  let parsed: TokenResponse | null = null;
  try {
    parsed = (await res.json()) as TokenResponse;
  } catch {
    parsed = null;
  }
  if (!res.ok || !parsed?.access_token) return { error: "rejected" };

  let sub: string | undefined;
  if (o.nonce) {
    const cl = idTokenClaims(parsed.id_token);
    const iss = cl?.iss;
    const okIss = iss === "https://accounts.google.com" || iss === "accounts.google.com";
    const aud = Array.isArray(cl?.aud) ? (cl?.aud as unknown[]).includes(c.clientId) : cl?.aud === c.clientId;
    const exp = typeof cl?.exp === "number" ? cl.exp : 0;
    if (!cl || !okIss || !aud || cl.nonce !== o.nonce || exp < Math.floor(Date.now() / 1000) - 60 || typeof cl.sub !== "string") {
      return { error: "nonce" };
    }
    sub = cl.sub;
  }
  return { accessToken: parsed.access_token, ...(sub ? { sub } : {}) };
}
