// "Continue with Google" on cyrus.my (CYRUS_GOOGLE_LOGIN). The protocol decisions only: no cookies, no Next, no
// session writes, so tests drive it with fakes. The route handlers (app/cyrus-host/auth/google[/callback]) do the I/O.
//
//   start    : state + nonce + PKCE verifier + validated `next` -> one sealed, short-lived, host-only cookie; the
//              browser goes to Google's consent screen with the Cyrus client.
//   callback : cookie (consumed) <-> state, Google code -> token (PKCE + nonce) -> userinfo -> the SAME Nxeon account
//              as Google login on nxeon.cloud (lib/google-account) -> Cyrus-host session (createCyrusSession, the
//              handoff's own minting path, no Nxeon parent session) -> private-beta rule -> `next`.
import { randomToken, safeEqual, seal, unseal } from "@/lib/cyrus/bridge/assertion";
import { bridgeConfig, type BridgeConfig } from "@/lib/cyrus/bridge/config";
import { safeCyrusNext } from "@/lib/cyrus/bridge/routing";
import type { GoogleError } from "@/lib/cyrus/bridge/flow";
import {
  cyrusGoogleConfigured,
  googleClientAuthorizeUrl,
  googleClientForHost,
  pkceChallenge,
  type GoogleClient,
  type GoogleProfile,
} from "@/lib/google-oauth";

type Env = Record<string, string | undefined>;
const STATE_PURPOSE = "google:cyrus";
export const GOOGLE_STATE_TTL_S = 600;

export type GoogleState = { s: string; n: string; v: string; next: string };

/** The state cookie's name (host-only `__Host-` in production, like the other Cyrus cookies). */
export const googleStateCookie = (env: Env = process.env) => `${env.NODE_ENV === "production" ? "__Host-" : ""}cyrus_google_state`;

/** The Cyrus client for this deployment, or null (flag off / not configured / mode off). */
export function cyrusGoogleClient(env: Env = process.env): GoogleClient | null {
  if (!cyrusGoogleConfigured(env)) return null;
  const cfg = bridgeConfig(env);
  return googleClientForHost(cfg.cyrusHosts[0], env);
}

export type StartPlan =
  | { kind: "redirect"; url: string; cookieValue: string; ttlS: number }
  | { kind: "error"; code: GoogleError };

export function planGoogleStart(o: { env?: Env; nextRaw: string | null | undefined; nowMs?: number }): StartPlan {
  const env = o.env ?? process.env;
  const client = cyrusGoogleClient(env);
  if (!client) return { kind: "error", code: "google_unavailable" };
  const st: GoogleState = { s: randomToken(24), n: randomToken(24), v: randomToken(48), next: safeCyrusNext(o.nextRaw) };
  return {
    kind: "redirect",
    url: googleClientAuthorizeUrl(client, { state: st.s, nonce: st.n, codeChallenge: pkceChallenge(st.v) }),
    cookieValue: seal(STATE_PURPOSE, st, GOOGLE_STATE_TTL_S, env as never, o.nowMs),
    ttlS: GOOGLE_STATE_TTL_S,
  };
}

export type AccountLike = { id: string; role: string; suspended: boolean | null };

export type CallbackDeps<U extends AccountLike> = {
  exchange: (c: GoogleClient, code: string, o: { codeVerifier: string; nonce: string }) => Promise<{ accessToken?: string; sub?: string; error?: string }>;
  fetchProfile: (accessToken: string) => Promise<{ profile?: GoogleProfile; error?: string }>;
  /** lib/google-account findOrCreateGoogleAccount (shared with nxeon.cloud's Google login). */
  resolve: (p: GoogleProfile) => Promise<{ ok: true; user: U; isNewAccount: boolean } | { ok: false }>;
  /** modBuilderAccess: may this account use the studio now (private-beta allow-list / public launch)? */
  allowed: (u: U) => Promise<boolean>;
};

export type CallbackResult<U> =
  | { kind: "fail"; code: GoogleError | "account" | "staff" | "ratelimited"; user?: U }
  | { kind: "ok"; user: U; isNewAccount: boolean; dest: string; allowed: boolean };

export async function completeGoogleLogin<U extends AccountLike>(o: {
  env?: Env;
  query: URLSearchParams;
  cookieRaw: string | null | undefined;
  deps: CallbackDeps<U>;
  nowMs?: number;
}): Promise<CallbackResult<U>> {
  const env = o.env ?? process.env;
  const client = cyrusGoogleClient(env);
  if (!client) return { kind: "fail", code: "google_unavailable" };
  const st = unseal<GoogleState & { e: number }>(STATE_PURPOSE, o.cookieRaw, env as never, o.nowMs);
  const state = o.query.get("state") ?? "";
  if (!st || !state || !safeEqual(st.s, state)) return { kind: "fail", code: "google_state" };
  const err = o.query.get("error");
  if (err) return { kind: "fail", code: err === "access_denied" ? "google_cancelled" : "google_failed" };
  const code = o.query.get("code") ?? "";
  if (!code || code.length > 2048) return { kind: "fail", code: "google_failed" };

  const tok = await o.deps.exchange(client, code, { codeVerifier: st.v, nonce: st.n });
  if (!tok.accessToken) return { kind: "fail", code: "google_failed" };
  const { profile } = await o.deps.fetchProfile(tok.accessToken);
  if (!profile) return { kind: "fail", code: "google_failed" };
  // The id_token (nonce-checked) and userinfo must describe the same Google account.
  if (tok.sub && tok.sub !== profile.sub) return { kind: "fail", code: "google_failed" };
  // Never link or create on an address Google did not verify.
  if (!profile.emailVerified) return { kind: "fail", code: "google_unverified" };

  const acct = await o.deps.resolve(profile);
  if (!acct.ok) return { kind: "fail", code: "google_failed" };
  const { user } = acct;
  if (user.suspended) return { kind: "fail", code: "account", user };
  // Same rule as /auth/handoff: staff accounts sign in to Nxeon with their password, never through a social login.
  if (user.role !== "CUSTOMER") return { kind: "fail", code: "staff", user };

  const dest = safeCyrusNext(st.next);
  // Not on the private-beta list: the sign-in page renders the beta panel for a signed-in account (never a 404). A
  // check error never blocks: the destination's own gate decides (same as /auth/nxeon/callback).
  const allowed = await o.deps.allowed(user).catch(() => true);
  return { kind: "ok", user, isNewAccount: acct.isNewAccount, dest, allowed };
}

/** Where to send the browser after a successful login. */
export const googleLandingPath = (r: { dest: string; allowed: boolean }) =>
  r.allowed ? r.dest : `/sign-in?next=${encodeURIComponent(r.dest)}`;

/**
 * HOOK (not implemented here): the Cyrus community username gate (feature/cyrus-community) runs first-run gating
 * after login. A signed-in account without a username is sent to its claim screen; return that path, or null to
 * continue to `dest`. Left as a no-op so that branch can fill it in without touching the protocol above.
 */
export function firstRunGate(_user: AccountLike, _dest: string): string | null {
  return null;
}

export type { BridgeConfig };
