import { cookies } from "next/headers";
import { bridgeConfig } from "@/lib/cyrus/bridge/config";
import { bridgeGate, go, limited, notFound } from "@/lib/cyrus-bridge/server";
import { googleStateCookie, planGoogleStart } from "@/lib/cyrus-bridge/google-login";

export const dynamic = "force-dynamic";

/**
 * cyrus.my "Continue with Google" start (public path /api/auth/google). Needs CYRUS_GOOGLE_LOGIN=1 + the Cyrus client;
 * otherwise back to sign-in with a fixed error. State + nonce + PKCE verifier + the validated `next` ride in ONE sealed,
 * httpOnly, host-only cookie; nothing sensitive is in a URL. Always runs on the canonical Cyrus origin so the cookie
 * and the registered redirect URI belong to the same host.
 */
export async function GET(req: Request) {
  const cfg = bridgeGate(req, "cyrus");
  if (!cfg) return notFound();
  const sp = new URL(req.url).searchParams;
  const origin = cfg.cyrusOrigin;
  if (limited(req, "google-start", 20)) return go(`${origin}/sign-in?error=ratelimited`);
  const host = (req.headers.get("host") ?? "").toLowerCase();
  if (host && host !== new URL(origin).host) {
    // www.cyrus.my etc: hop to the canonical host first (host-only cookies, one registered redirect URI)
    const q = sp.get("next") ? `?next=${encodeURIComponent(sp.get("next")!)}` : "";
    return go(`${origin}/api/auth/google${q}`);
  }
  const plan = planGoogleStart({ nextRaw: sp.get("next") });
  if (plan.kind === "error") return go(`${origin}/sign-in?error=${plan.code}`);
  (await cookies()).set(googleStateCookie(), plan.cookieValue, {
    httpOnly: true, sameSite: "lax", secure: process.env.NODE_ENV === "production", path: "/", maxAge: plan.ttlS,
  });
  void bridgeConfig;
  return go(plan.url);
}
