import { cookies } from "next/headers";
import { db } from "@/lib/db";
import { createCyrusSession } from "@/lib/auth";
import { recordRequestActivity } from "@/lib/activity-request";
import { modBuilderAccess } from "@/lib/modbuilder/access";
import { googleClientExchange, googleFetchProfile } from "@/lib/google-oauth";
import { findOrCreateGoogleAccount } from "@/lib/google-account";
import { bridgeGate, go, limited, notFound } from "@/lib/cyrus-bridge/server";
import { completeGoogleLogin, firstRunGate, googleLandingPath, googleStateCookie } from "@/lib/cyrus-bridge/google-login";

export const dynamic = "force-dynamic";

/**
 * cyrus.my Google callback (registered redirect URI https://<cyrus host>/api/auth/google/callback). The protocol is in
 * lib/cyrus-bridge/google-login; here: the state cookie is consumed, the session is the Cyrus-host cookie minted by
 * the same createCyrusSession the Nxeon-SSO callback uses, and every failure lands on /sign-in with a fixed code.
 */
export async function GET(req: Request) {
  const cfg = bridgeGate(req, "cyrus");
  if (!cfg) return notFound();
  const fail = (code: string) => go(`${cfg.cyrusOrigin}/sign-in?error=${encodeURIComponent(code)}`);
  const jar = await cookies();
  const name = googleStateCookie();
  const raw = jar.get(name)?.value;
  // one callback per start: a __Host- cookie is only cleared by a Secure Set-Cookie with path=/
  jar.set(name, "", { httpOnly: true, sameSite: "lax", secure: process.env.NODE_ENV === "production", path: "/", maxAge: 0 });
  if (limited(req, "google-callback")) return fail("ratelimited");

  const r = await completeGoogleLogin({
    query: new URL(req.url).searchParams,
    cookieRaw: raw,
    deps: {
      exchange: googleClientExchange,
      fetchProfile: googleFetchProfile,
      resolve: async (p) => {
        const a = await findOrCreateGoogleAccount(p, { headers: req.headers });
        return a.ok ? a : { ok: false };
      },
      allowed: async (u) => !!(await modBuilderAccess(u)),
    },
  });

  if (r.kind === "fail") {
    if (r.user) await db.auditLog.create({ data: { userId: r.user.id, action: "user.login_denied", detail: `Google (cyrus.my): ${r.code}` } }).catch(() => {});
    return fail(r.code);
  }
  await db.auditLog.create({ data: { userId: r.user.id, action: "user.login", detail: "Google (cyrus.my)" } }).catch(() => {});
  await recordRequestActivity({ type: "auth.login", userId: r.user.id, label: "Signed in to Cyrus with Google (cyrus.my)", data: { method: "google-cyrus" } }, { headers: req.headers });
  // No Nxeon parent session exists on this path (identity came straight from Google), so the Cyrus session stands alone.
  await createCyrusSession(r.user.id, null);
  const gate = firstRunGate(r.user, r.dest);
  return go(`${cfg.cyrusOrigin}${gate ?? googleLandingPath(r)}`);
}
