    const staff = await completeGoogleLogin({ env, query: q({ state: s.state, code: "c" }), cookieRaw: s.cookie, deps: deps({ user: { id: "u", role: "ADMIN", suspended: false } }).deps });
    assert.equal(staff.kind === "fail" && staff.code, "staff");
    const beta = await completeGoogleLogin({ env, query: q({ state: s.state, code: "c" }), cookieRaw: s.cookie, deps: deps({ allowed: false }).deps });
    assert.equal(beta.kind, "ok");
    if (beta.kind === "ok") assert.equal(googleLandingPath(beta), "/sign-in?next=%2Fstudio");
  });
  it("an allow-list check that throws never blocks", async () => {
    const s = begin(), d = deps();
    d.deps.allowed = async () => { throw new Error("db"); };
    const r = await completeGoogleLogin({ env, query: q({ state: s.state, code: "c" }), cookieRaw: s.cookie, deps: d.deps });
    assert.equal(r.kind === "ok" && r.allowed, true);
  });
  it("next is re-validated: an off-site or non-Cyrus next in the state becomes /studio", async () => {
    for (const bad of ["https://evil.test/", "//evil.test", "/admin", "/\\evil"]) {
      const p = planGoogleStart({ env, nextRaw: bad }) as { cookieValue: string; url: string };
      const r = await completeGoogleLogin({ env, query: q({ state: url(p.url).get("state")!, code: "c" }), cookieRaw: p.cookieValue, deps: deps().deps });
      assert.equal(r.kind === "ok" && r.dest, "/studio", bad);
    }
  });
  it("the username-gate hook is a no-op by default", () => assert.equal(firstRunGate({ id: "u", role: "CUSTOMER", suspended: false }, "/studio"), null));
  it("error codes render fixed copy and unknown codes render nothing", () => {
    for (const c of ["google_unavailable", "google_cancelled", "google_failed", "google_state", "google_unverified"]) assert.ok(bridgeErrorText(c), c);
    assert.equal(bridgeErrorText("<script>"), null);
  });
});

describe("token exchange (fake Google token endpoint)", () => {
  const client = googleClientForHost("cyrus.my", env)!;
  const idToken = (c: Record<string, unknown>) => `x.${Buffer.from(JSON.stringify(c)).toString("base64url")}.y`;
  const good = { iss: "https://accounts.google.com", aud: env.CYRUS_GOOGLE_CLIENT_ID, nonce: "N1", sub: "g-sub-1", exp: Math.floor(Date.now() / 1000) + 600 };
  function fake(status: number, body: unknown) {
    const seen: { url: string; body: URLSearchParams }[] = [];
    globalThis.fetch = (async (u: string, init: { body: string }) => {
      seen.push({ url: String(u), body: new URLSearchParams(init.body) });
      return new Response(JSON.stringify(body), { status });
    }) as never;
    return seen;
  }
  it("posts the Cyrus client, exact redirect_uri and the PKCE verifier; checks the nonce", async () => {
    const seen = fake(200, { access_token: "at", id_token: idToken(good) });
    const r = await googleClientExchange(client, "CODE", { codeVerifier: "VERIFIER", nonce: "N1" });
    assert.deepEqual(r, { accessToken: "at", sub: "g-sub-1" });
    assert.equal(seen[0].url, "https://oauth2.googleapis.com/token");
    assert.equal(seen[0].body.get("client_id"), env.CYRUS_GOOGLE_CLIENT_ID);
    assert.equal(seen[0].body.get("redirect_uri"), "https://cyrus.my/api/auth/google/callback");
    assert.equal(seen[0].body.get("code_verifier"), "VERIFIER");
    assert.equal(seen[0].body.get("grant_type"), "authorization_code");
  });
  it("rejects a wrong nonce, audience, issuer, expiry or a missing id_token", async () => {
    for (const bad of [{ ...good, nonce: "other" }, { ...good, aud: "someone-else" }, { ...good, iss: "https://evil.test" }, { ...good, exp: 1 }]) {
      fake(200, { access_token: "at", id_token: idToken(bad) });
      assert.deepEqual(await googleClientExchange(client, "C", { codeVerifier: "V", nonce: "N1" }), { error: "nonce" });
    }
    fake(200, { access_token: "at" });
    assert.deepEqual(await googleClientExchange(client, "C", { codeVerifier: "V", nonce: "N1" }), { error: "nonce" });
  });
  it("Google rejection and network failure give safe codes without any detail", async () => {
    fake(400, { error: "invalid_grant", error_description: "secret detail" });
    assert.deepEqual(await googleClientExchange(client, "C", { nonce: "N1" }), { error: "rejected" });
    globalThis.fetch = (async () => { throw new Error("boom"); }) as never;
    assert.deepEqual(await googleClientExchange(client, "C", { nonce: "N1" }), { error: "network" });
  });
  it("authorize URL helper omits PKCE/nonce when not asked", () => {
    const u = googleClientAuthorizeUrl(client, { state: "S" });
    assert.ok(!u.includes("code_challenge") && !u.includes("nonce"));
  });
});

describe("routing on the Cyrus host", () => {
  const cfg = bridgeConfig(env);
  it("the redirect URI path and the start path are rewritten to the Cyrus-host handlers", () => {
    assert.deepEqual(cyrusHostRoute({ pathname: "/api/auth/google/callback", search: "?code=x", method: "GET", cfg }), { kind: "rewrite", pathname: "/cyrus-host/auth/google/callback" });
    assert.deepEqual(cyrusHostRoute({ pathname: "/api/auth/google", search: "", method: "GET", cfg }), { kind: "rewrite", pathname: "/cyrus-host/auth/google" });
  });
  it("other /api/auth paths still 404 on the Cyrus host", () => {
    assert.deepEqual(cyrusHostRoute({ pathname: "/api/auth/google/other", search: "", method: "GET", cfg }), { kind: "notfound" });
    assert.deepEqual(cyrusHostRoute({ pathname: "/api/auth/login", search: "", method: "GET", cfg }), { kind: "notfound" });
  });
});
